                echo "Pipeline finalizer: waiting for job $job_id to stop (state: $state)"
                sleep 5
            done
            printf 'job_id=%s\nstate=CANCELLED_BY_JENKINS\nexit_code=\n' "$job_id" > "$status_file"
        done
    '''
}

if (!(params.PR_NUMBER ==~ /[1-9][0-9]*/)) {
    error("PR_NUMBER must be a positive integer, got '${params.PR_NUMBER}'.")
}

def nodeLabel = (env.STELLAR_INTEL_NODE_LABEL ?: 'stellar-intel').trim()
def gkeyllCiRoot = requireValue('GKEYLL_CI_ROOT', env.GKEYLL_CI_ROOT)
def workspaceRoot = "${gkeyllCiRoot}/workspaces"
def credentialsId = requireValue('STELLAR_GITHUB_CREDENTIAL_ID', env.STELLAR_GITHUB_CREDENTIAL_ID)
def prCommit = ''
def terminalStatus = 'failure'
def terminalDescription = 'Stellar Intel CPU CI failed.'

node(nodeLabel) {
    // Stellar compute nodes must see this path. Configure the root on a shared
    // filesystem such as the project's /scratch/gpfs location, never /tmp.
    ws("${workspaceRoot}/${env.JOB_NAME}/${env.BUILD_TAG}") {
        try {
            stage('Checkout PR') {
                deleteDir()
                checkoutPullRequest(credentialsId)
                prCommit = sh(returnStdout: true, script: 'git rev-parse HEAD').trim()
                writeFile file: 'ci-pr-commit.txt', text: "${prCommit}\n"
                sh 'git status --short'
            }
            stage('Report pending to GitHub') {
                publishGitHubCommitStatus(
                    credentialsId,
                    prCommit,
                    'pending',
                    'Stellar Intel CPU CI is running.'
                )
            }
            stage('Build dependencies') {
                withEnv(["PREFIX=${env.WORKSPACE}/gkylsoft"]) {
                    sh '''#!/bin/bash -l
                        set -euo pipefail
                        ./machines/mkdeps.stellar-intel.sh
                    '''
                }
            }
            stage('Configure') {
                withEnv(["PREFIX=${env.WORKSPACE}/gkylsoft"]) {
                    sh '''#!/bin/bash -l
                        set -euo pipefail
                        ./machines/configure.stellar-intel.sh
                    '''
                }
            }
            stage('Build unit tests') {
                def jobs = buildJobs()
                sh """#!/bin/bash -l
                    set -euo pipefail
                    # Each Jenkins sh step is a new process, so source the
                    # same environment used by the Stellar machine scripts.
                    . machines/module_load.stellar-intel.sh
                    module list
                    make -j${jobs} unit
                """
            }
            stage('Run unit tests (SLURM)') {
                submitUnitTests()
            }
            stage('Install PR for C regression') {
                def jobs = buildJobs()
                sh """#!/bin/bash -l
                    set -euo pipefail
                    . machines/module_load.stellar-intel.sh
                    make -j${jobs} install
                """
            }
            stage('Compile PR C regressions') {
                configureAndCompileCRegressions(
                    "${env.WORKSPACE}/gkylsoft/gkeyll/bin/gkeyll",
                    env.WORKSPACE,
                    "${env.WORKSPACE}/gkylsoft",
                    'machines/module_load.stellar-intel.sh'
                )
            }
            stage('Checkout agent_tools-jenkins baseline') {
                dir('_baseline') {
                    deleteDir()
                    checkoutRegressionBaseline(credentialsId)
                    sh 'git rev-parse HEAD | tee ../ci-baseline-commit.txt'
                }
            }
            stage('Build agent_tools-jenkins baseline') {
                withEnv(["PREFIX=${env.WORKSPACE}/_baseline/gkylsoft"]) {
                    dir('_baseline') {
                        sh '''#!/bin/bash -l
                            set -euo pipefail
                            . ../machines/module_load.stellar-intel.sh
                            ./machines/mkdeps.stellar-intel.sh
                            ./machines/configure.stellar-intel.sh
                        '''
                    }
                }
            }
            stage('Install agent_tools-jenkins baseline') {
                def jobs = buildJobs()
                dir('_baseline') {
                    sh """#!/bin/bash -l
                        set -euo pipefail
                        . ../machines/module_load.stellar-intel.sh
                        make -j${jobs} install
                    """
                }
            }
            stage('Compile agent_tools-jenkins C regressions') {
                // The baseline branch predates the compile/execute-only
                // interface. Use the PR-side runner only as the driver; its
                // source tree, installed Makefile, libraries, and generated
                // baseline outputs are all selected by these baseline paths.
                configureAndCompileCRegressions(
                    "${env.WORKSPACE}/gkylsoft/gkeyll/bin/gkeyll",
                    "${env.WORKSPACE}/_baseline",
                    "${env.WORKSPACE}/_baseline/gkylsoft",
                    'machines/module_load.stellar-intel.sh'
                )
            }
            stage('Run C regressions (SLURM)') {
                submitRegressionTests()
            }
            terminalStatus = 'success'
            terminalDescription = 'Stellar Intel CPU unit and C regression tests passed.'
        } catch (err) {
            if (currentBuild.currentResult == 'ABORTED' || err.toString().contains('FlowInterruptedException')) {
                terminalStatus = 'error'
                terminalDescription = 'Stellar Intel CPU CI was aborted.'
            }
            throw err
        } finally {
            try {
                finalizeUnfinishedSlurmJob()
            } catch (err) {
                terminalStatus = 'error'
                terminalDescription = 'Stellar Intel CPU CI cleanup failed.'
                throw err
            } finally {
                try {
                    archiveArtifacts allowEmptyArchive: true,
                        artifacts: 'ci-pr-commit.txt,ci-baseline-commit.txt,slurm-*.out,slurm-*-job-id.txt,slurm-*-job-status.txt,build/**/*.log,gkylsoft/gkeyll-results/**/regressiondb,gkylsoft/gkeyll-results/**/_rr_failures.txt,_baseline/gkylsoft/gkeyll-results/**/regressiondb,_baseline/gkylsoft/gkeyll-results/**/_rr_failures.txt'
                } catch (err) {
                    terminalStatus = 'error'
                    terminalDescription = 'Stellar Intel CPU CI artifact archival failed.'
                    throw err
                } finally {
                    try {
                        if (prCommit) {
                            publishGitHubCommitStatus(
                                credentialsId,
                                prCommit,
                                terminalStatus,
                                terminalDescription
                            )
                        }
                    } finally {
                        deleteDir()
                    }
                }
            }
        }
    }
}

--- regression runner ---
#!/bin/bash -l
# All-C regression payload for ci/jenkins/Jenkinsfile.stellar-intel.
#
# Jenkins builds, installs, and compiles the PR and trusted baseline on the
# login node. This payload only executes their precompiled C tests, creates
# the baseline's outputs, checks the PR against them, and turns SQLite-recorded
# failures into a Slurm/Jenkins failure.
set -euo pipefail

: "${CI_WORKSPACE:?CI_WORKSPACE must name the shared Jenkins workspace}"
: "${CI_BASELINE_DIR:?CI_BASELINE_DIR must name the trusted baseline checkout}"
: "${CI_BASELINE_PREFIX:?CI_BASELINE_PREFIX must name the baseline install prefix}"
: "${CI_PR_PREFIX:?CI_PR_PREFIX must name the PR install prefix}"
: "${CI_REGRESSION_JOBS:?CI_REGRESSION_JOBS must be set}"
: "${CI_REGRESSION_TEST_TIMEOUT:?CI_REGRESSION_TEST_TIMEOUT must be set}"

cd "$CI_WORKSPACE"
. machines/module_load.stellar-intel.sh

baseline_gkeyll="$CI_BASELINE_PREFIX/gkeyll/bin/gkeyll"
pr_gkeyll="$CI_PR_PREFIX/gkeyll/bin/gkeyll"

test -x "$baseline_gkeyll"
test -x "$pr_gkeyll"

# The PR-side runner provides the compile/execute-only interface. It drives
# baseline tests through their own source directory and install prefix, so the
# tested baseline executable and libraries still come from agent_tools-jenkins.
cd "$CI_BASELINE_DIR"
"$pr_gkeyll" runregression run -c --execute-only create \
  --jobs "$CI_REGRESSION_JOBS" \
  --timeout "$CI_REGRESSION_TEST_TIMEOUT"

cd "$CI_WORKSPACE"
# Use only C accepted output from the fixed baseline. Do not carry Lua
# baselines into this CPU C-regression job.
for layer in moments vlasov gyrokinetic pkpm; do
  baseline_accepted="$CI_BASELINE_PREFIX/gkeyll-results/$layer/creg-accepted"
  pr_accepted="$CI_PR_PREFIX/gkeyll-results/$layer/creg-accepted"
  rm -rf "$pr_accepted"
  if [[ -d "$baseline_accepted" ]]; then
    mv "$baseline_accepted" "$pr_accepted"
  fi
done

"$pr_gkeyll" runregression run -c --execute-only check \
  --jobs "$CI_REGRESSION_JOBS" \
  --timeout "$CI_REGRESSION_TEST_TIMEOUT"
"$pr_gkeyll" ci/jenkins/check_regression_results.lua \
  "$CI_PR_PREFIX/gkeyll-results" \
  ci/jenkins/expected_regression_diffs.txt

